"use strict";(function(){function p(t){let e=(n,...i)=>l(o(t,n),n,...i).join("");return e.asArray=(n,...i)=>l(o(t,n),...i),e}function s(t){let e=(...n)=>l(t,...n).join("");return e.asArray=(...n)=>l(t,...n),e}function o(t,e){return t[i18n.quantity(e)]||t.other||t.one||""}function l(t,...e){let n=t.split(/(%(?:\d\$)?s)/);if(e.length){let i=n.indexOf("%s");if(i!=-1)n[i]=e[0];else for(let r=0;r<e.length;r++){let f=n.indexOf("%"+(r+1)+"$s");f!=-1&&(n[f]=e[r])}}return n}
let i=window.i18n.puzzleTheme={};i['advancedPawn']="Προχωρημένο πιόνι";i['advancedPawnDescription']="Ένα πιόνι έχει προχωρήσει πολύ και απειλεί να προαχθεί.";i['advantage']="Πλεονέκτημα";i['advantageDescription']="Εκμεταλλευτείτε κάθε δυνατή ευκαιρία για να αποκτήσετε καθοριστικό πλεονέκτημα. (200cp ≤ eval ≤ 600cp)";i['anastasiaMate']="To ματ της Αναστασίας";i['anastasiaMateDescription']="Ένας ίππος και ένας πύργος ή μια βασίλισσα συνεργάζονται για να κάνουν ματ, παγιδεύοντας τον αντίπαλο βασιλιά μεταξύ της άκρης της σκακιέρας και ενός φιλικού κομματιού.";i['arabianMate']="Αραβικό ματ";i['arabianMateDescription']="Ένας ίππος και ένας πύργος συνεργάζονται για να κάνουν ματ παγιδεύοντας τον αντίπαλο βασιλιά σε μια γωνία της σκακιέρας.";i['attackingF2F7']="Επίθεση στο f2 ή f7";i['attackingF2F7Description']="Μια επίθεση που εστιάζει στο πιόνι f2 ή f7, όπως στο άνοιγμα Fried Liver Attack.";i['attraction']="Έλξη";i['attractionDescription']="Μια αλλαγή ή θυσία ελκύει ή αναγκάζει ένα αντίπαλο κομμάτι να μετακινηθεί σε ένα τετράγωνο και οδηγεί σε τακτικό.";i['backRankMate']="Ματ τελευταίας γραμμής";i['backRankMateDescription']="Κάντε ματ στον βασιλιά στην τελευταία γραμμή όταν είναι παγιδευμένος εκεί από τα κομμάτια του.";i['balestraMate']="Ματ-βαλλίστρα";i['balestraMateDescription']="Ένας αξιωματικός κάνει ματ στον αντίπαλο βασιλιά, ενώ η βασίλισσα εμποδίζει τη διαφυγή του στα γειτονικά τετράγωνα";i['bishopEndgame']="Φινάλε αξιωματικών";i['bishopEndgameDescription']="Φινάλε μόνο με αξιωματικούς και πιόνια.";i['blindSwineMate']="Ματ Blind Swine";i['blindSwineMateDescription']="Δύο πύργοι συνεργάζονται προκειμένου να κάνουν ματ στον αντίπαλο βασιλιά παγιδεύοντάς τον σε μία περιοχή 2 επί 2 τετραγώνων της σκακιέρας.";i['bodenMate']="Ματ του Boden";i['bodenMateDescription']="Δύο αξιωματικοί κινούνται διαγωνίως και κάνουν ματ σε βασιλιά που εμποδίζεται από δικά του κομμάτια.";i['capturingDefender']="Αιχμαλώτιση αμυνόμενου κομματιού";i['capturingDefenderDescription']="Απομάκρυνση κομματιού που είναι σημαντικό για την υπεράσπιση άλλου κομματιού, επιτρέποντας την αιχμαλώτιση του πλέον ανυπεράσπιστου κομματιού στην επόμενη κίνηση.";i['castling']="Pοκέ";i['castlingDescription']="Ασφαλίστε τον βασιλιά και αναπτύξτε τον πύργο για επίθεση.";i['clearance']="Απελευθέρωση";i['clearanceDescription']="Μία κίνηση, συνήθως με tempo, που ελευθερώνει ένα τετράγωνο, μια στήλη ή μια διαγώνιο για την ολοκλήρωση ενός τακτικού.";i['collinearMove']="Συγγραμμική κίνηση";i['collinearMoveDescription']="Δύο αντίπαλα κομμάτια κοιτάζουν το ένα το άλλο, και το ένα κινείται κατά μήκος της γραμμής χωρίς να τρώει το εχθρικό κομμάτι.";i['cornerMate']="Ματ στη γωνία";i['cornerMateKnightDeliversDescription']="Confine the king to the corner using a rook or queen, and use a knight to deliver the checkmate.";i['crushing']="Σαρωτική επίθεση";i['crushingDescription']="Εντοπίστε το σοβαρό λάθος του αντιπάλου και αποκτήστε καθοριστικό πλεονέκτημα. (eval ≥ 600cp)";i['defensiveMove']="Αμυντική κίνηση";i['defensiveMoveDescription']="Μια κίνηση ή μια ακολουθία κινήσεων που απαιτείται για να αποφευχθεί η απώλεια υλικού και γενικά οποιουδήποτε πλεονεκτήματος.";i['deflection']="Αντιπερισπασμός";i['deflectionDescription']="Μία κίνηση που απομακρύνει ένα αντίπαλο κομμάτι από κάποιο άλλο του καθήκον, όπως η φύλαξη ενός σημαντικού τετραγώνου. Ονομάζεται ενίοτε και \"υπερφόρτωση\".";i['discoveredAttack']="Αποκάλυψη";i['discoveredAttackDescription']="Μετακίνηση ενός κομματιού (π.χ. ίππου) που εμποδίζει την επίθεση άλλου κομματιού μεγάλης εμβέλειας (π.χ. πύργου).";i['discoveredCheck']="Σαχ με αποκάλυψη";i['discoveredCheckDescription']="Μετακινήστε ένα κομμάτι ώστε ένα άλλο κομμάτι να αποκαλυφθεί και να δώσει σαχ, αποκτώντας παράλληλα ένα αποφασιστικό πλεονέκτημα.";i['doubleBishopMate']="Ματ με δύο αξιωματικούς";i['doubleBishopMateDescription']="Δύο αξιωματικοί σε γειτονικές διαγώνιους κάνουν ματ σε βασιλιά που εμποδίζεται από δικά του κομμάτια.";i['doubleCheck']="Διπλό σαχ";i['doubleCheckDescription']="Ταυτόχρονο σαχ από δύο κομμάτια, ως αποτέλεσμα αποκάλυψης: τόσο το κομμάτι που μετακινήθηκε όσο και το κομμάτι το οποίο αποκάλυψε απειλούν τον αντίπαλο βασιλιά.";i['dovetailMate']="Dovetail ματ";i['dovetailMateDescription']="Βασίλισσα κάνει ματ στον αντίπαλο βασιλιά, του οποίου τα μοναδικά δύο τετράγωνα διαφυγής καλύπτονται από φιλικά κομμάτια.";i['endgame']="Φινάλε";i['endgameDescription']="Τακτικά στην τελευταία φάση της παρτίδας.";i['enPassantAdjacentCaptureDescription']="Τακτική με «αν πασάν», όπου ένα πιόνι αιχμαλωτίζει το αντίπαλο πιόνι το οποίο έκανε την αρχική του κίνηση δύο τετραγώνων.";i['epauletteMate']="Ματ των επωμίδων";i['epauletteMateDescription']="Ένας βασιλιάς στην άκρη της σκακιέρας δέχεται σαχ και τα δύο γειτονικά τετράγωνα διαφυγής του είναι κατειλημμένα από φιλικά κομμάτια.";i['equality']="Ισότητα";i['equalityDescription']="Ανακάμψτε από μια χαμένη θέση και εξασφαλίστε ισοπαλία ή μια ισορροπημένη θέση. (eval ≤ 200cp)";i['exposedKing']="Ευάλωτος βασιλιάς";i['exposedKingDescription']="Τακτικά τα οποία αφορούν έναν βασιλιά με λίγα αμυντικά κομμάτια γύρω του, και τα οποία συχνά καταλήγουν σε ματ.";i['fork']="Πιρούνι – Διπλό χτύπημα";i['forkOpposingPiecesDescription']="Κίνηση κατά την οποία ένα κομμάτι απειλεί ταυτόχρονα δύο ή περισσότερα αντίπαλα κομμάτια.";i['hangingPiece']="Κομμάτι που κρέμεται";i['hangingPieceDescription']="Τακτικά στα οποία ένα αντίπαλο κομμάτι «κρέμεται» — είναι, δηλαδή, απροστάτευτο ή δεν προστατεύεται επαρκώς και μπορεί, κατά συνέπεια, να αιχμαλωτιστεί.";i['hookMate']="Ματ με αγκίστρι";i['hookMateOpposingPawnDescription']="Ματ με πύργο, ίππο και πιόνι, κατά το οποίο ένα αντίπαλο πιόνι εμποδίζει τη διαφυγή του βασιλιά.";i['interference']="Παρεμβολή";i['interferenceDescription']="Μετακίνηση κομματιού ανάμεσα σε δύο αντίπαλα κομμάτια, η οποία έχει σκοπό να αφήσει ένα ή και τα δύο αντίπαλα κομμάτια απροστάτευτα. Χαρακτηριστικό παράδειγμα αποτελεί η μετακίνηση ενός ίππου ανάμεσα από δύο αντίπαλους πύργους.";i['intermezzo']="Ενδιάμεση κίνηση";i['intermezzoDescription']="Αντί για την αναμενόμενη κίνηση παίζεται πρώτα κάποια ενδιάμεση κίνηση που δημιουργεί μια απειλή την οποία ο αντίπαλος πρέπει να αντιμετωπίσει αμέσως. Επίσης γνωστό ως \"Zwischenzug\" ή \"Intermezzo\".";i['killBoxMate']="Ματ του κουτιού εξόντωσης";i['killBoxMateDescription']="Ένας πύργος βρίσκεται δίπλα από τον αντίπαλο βασιλιά και υποστηρίζεται από τη βασίλισσα η οποία εμποδίζει τα τετράγωνα διαφυγής του βασιλιά. Ο πύργος και η βασίλισσα εγκλωβίζουν τον αντίπαλο βασιλιά σε ένα 3 επί 3 «κουτί εξόντωσης».";i['kingsideAttack']="Επίθεση στην πλευρά του βασιλιά";i['kingsideAttackDescription']="Επίθεση στον αντίπαλο βασιλιά, μετά από μικρό ροκέ.";i['knightEndgame']="Φινάλε ίππων";i['knightEndgameDescription']="Φινάλε μόνο με ίππους και πιόνια.";i['long']="Μεγάλο τακτικό";i['longDescription']="Τρεις κινήσεις για να κερδίσετε.";i['master']="Παρτίδες κορυφαίων παικτών";i['masterDescription']="Τακτικά από παρτίδες τιτλούχων παικτών.";i['masterVsMaster']="Παρτίδες μεταξύ κορυφαίων παικτών";i['masterVsMasterDescription']="Τακτικά από παρτίδες μεταξύ δύο τιτλούχων παικτών.";i['mate']="Ματ";i['mateDescription']="Κερδίστε το παιχνίδι με στυλ.";i['mateIn1']="Ματ σε 1";i['mateIn1Description']="Κάντε ματ με μια κίνηση.";i['mateIn2']="Ματ σε 2";i['mateIn2Description']="Κάντε ματ σε δύο κινήσεις.";i['mateIn3']="Ματ σε 3";i['mateIn3Description']="Κάντε ματ σε τρεις κινήσεις.";i['mateIn4']="Ματ σε 4";i['mateIn4Description']="Κάντε ματ σε τέσσερις κινήσεις.";i['mateIn5']="Ματ σε 5 ή περισσότερο";i['mateIn5Description']="Βρείτε μία μακρά ακολουθία κινήσεων που οδηγεί σε ματ.";i['middlegame']="Μέσο";i['middlegameDescription']="Τακτικά κατά τη δεύτερη φάση της παρτίδας.";i['mix']="Προτεινόμενο μίγμα";i['mixDescription']="Λίγο απ' όλα. Δεν ξέρετε τι να περιμένετε, οπότε παραμένετε σε ετοιμότητα! Όπως ακριβώς και στις πραγματικές παρτίδες.";i['morphyMateBishopAndRookDescription']="Ο αξιωματικός κάνει ματ στον βασιλιά που περιορίζεται από έναν πύργο.";i['morphysMate']="Ματ του Μόρφυ";i['oneMove']="Τακτικό μιας κίνησης";i['oneMoveDescription']="Τακτικά που έχουν μόνο μία κίνηση.";i['opening']="Άνοιγμα";i['openingDescription']="Τακτικά κατά την πρώτη φάση της παρτίδας.";i['operaMate']="Ματ της όπερας";i['operaMateDescription']="Ένας πύργος που προστατεύεται από έναν αξιωματικό κάνει ματ στον αντίπαλο βασιλιά.";i['pawnEndgame']="Φινάλε πιονιών";i['pawnEndgameDescription']="Φινάλε μόνο με πιόνια.";i['pillsburyMateRookAndBishopDescription']="Ο πύργος κάνει ματ τον βασιλιά με την βοήθεια ενός αξιωματικού.";i['pillsburysMate']="Ματ του Πίλσμπερι";i['pin']="Κάρφωμα";i['pinDescription']="Τακτικά που περιλαμβάνουν καρφώματα. Ένα κομμάτι είναι καρφωμένο όταν αδυνατεί να μετακινηθεί χωρίς να αποκαλύψει μια επίθεση σε ένα κομμάτι μεγαλύτερης αξίας.";i['playerGames']="Παρτίδες παίκτη";i['playerGamesDescription']="Αναζητήστε τακτικά που προήλθαν από παρτίδες είτε δικές σας είτε άλλων χρηστών.";i['promotePawnToQueenRookOrMinor']="Promote one of your pawns to a queen, rook or minor piece.";i['promotion']="Προαγωγή";i['puzzleDownloadInformation']=s("Τα τακτικά είναι δημόσια και διαθέσιμα για λήψη στην ιστοσελίδα %s.");i['queenEndgame']="Φινάλε βασιλισσών";i['queenEndgameDescription']="Φινάλε μόνο με βασίλισσες και πιόνια.";i['queenRookEndgame']="Βασίλισσα και πύργος";i['queenRookEndgameDescription']="Ένα φινάλε μόνο με βασίλισσες, πύργους και πιόνια.";i['queensideAttack']="Επίθεση στην πλευρά της βασίλισσας";i['queensideAttackDescription']="Επίθεση στον αντίπαλο βασιλιά, μετά από μεγάλο ροκέ.";i['quietMove']="Ήσυχη κίνηση";i['quietMoveDescription']="Μια κίνηση που δε δίνει σαχ ούτε αιχμαλωτίζει κάποιο αντίπαλο κομμάτι, αλλά προετοιμάζει μια αναπόφευκτη κρυφή απειλή σε επόμενη κίνηση.";i['rookEndgame']="Φινάλε πύργων";i['rookEndgameDescription']="Ένα φινάλε μόνο με πύργους και πιόνια.";i['sacrifice']="Θυσία";i['sacrificeDescription']="Τακτικά στα οποία ένα κομμάτι θυσιάζεται με σκοπό η βραχυπρόθεσμη αυτή απώλεια υλικού να αντισταθμιστεί, ύστερα από ακολουθία φορσέ κινήσεων, από την απόκτηση καθοριστικού πλεονεκτήματος.";i['short']="Σύντομο τακτικό";i['shortDescription']="Δύο κινήσεις για να κερδίσετε.";i['skewer']="Σούβλισμα";i['skewerDescription']="Ένα μοτίβο όπου ένα κομμάτι μεγάλης αξίας δέχεται επίθεση, μετακινείται, και επιτρέπει την επίθεση ή την αιχμαλώτιση ενός κομματιού μικρότερης αξίας πίσω από αυτό, το αντίστροφο δηλαδή του καρφώματος.";i['smotheredMate']="Ματ αποπνιγμού";i['smotheredMateDescription']="Ένα ματ που γίνεται από έναν ίππο στον αντίπαλο βασιλιά ο οποίος δεν μπορεί να μετακινηθεί όντας περιτριγυρισμένος (ή πνιγμένος) από δικά του κομμάτια.";i['superGM']="Παιχνίδια κορυφαίων GM";i['superGMDescription']="Τακτικά από παρτίδες οι οποίες παίχτηκαν από κορυφαίους παίκτες του κόσμου.";i['swallowstailMate']="Ματ χελιδονοουράς";i['swallowstailMateDescription']="Ένα μοτίβο ματ που οπτικά μοιάζει με την ουρά ενός χελιδονιού, παρόμοιο με το σχήμα V.";i['trappedPiece']="Παγιδευμένο κομμάτι";i['trappedPieceDescription']="Ένα κομμάτι δεν μπορεί να αποφύγει την αιχμαλώτιση, καθώς έχει περιορισμένες κινήσεις.";i['triangleMate']="Τριγωνικό ματ";i['triangleMateDescription']="Η βασίλισσα και ο πύργος βρίσκονται ένα τετράγωνο μακριά από στον αντίπαλο βασιλιά και είναι στην ίδια γραμμή ή στην ίδια στήλη, ενώ χωρίζονται μεταξύ τους από ένα τετράγωνο, σχηματίζοντας κατά τον τρόπο αυτό ένα τρίγωνο.";i['underPromotion']="Προαγωγή σε κομμάτι μικρότερης αξίας";i['underPromotionDescription']="Προαγωγή σε ίππο, αξιωματικό ή πύργο.";i['veryLong']="Πολύ μεγάλο τακτικό";i['veryLongDescription']="Τέσσερις κινήσεις ή περισσότερα για να κερδίσετε.";i['vukovicMate']="Ματ του Vukovic";i['vukovicMateDescription']="Ένας πύργος και ένας ίππος συνεργάζονται για να κάνουν ματ στην άκρη της σκακιέρας. Ο πύργος κάνει ματ υποστηριζόμενος από κάποιο άλλο κομμάτι, ενώ ο ίππος ελέγχει όλα τα υπόλοιπα πιθανά τετράγωνα διαφυγής του αντίπαλου βασιλιά.";i['xRayAttack']="Ακτίνες X";i['xRayAttackDescription']="Κομμάτι αμύνεται ή επιτίθεται σε ένα τετράγωνο, αξιοποιώντας ένα αντίπαλο κομμάτι.";i['zugzwang']="Τσούγκτσβανγκ";i['zugzwangDescription']="Ο αντίπαλος δεν έχει καμία καλή κίνηση — κάθε πιθανή του κίνηση χειροτερεύει τη θέση του.";i['cornerMateDescription']="Ο πύργος ή η βασίλισσα περιορίζουν τον αντίπαλο βασιλιά στη γωνία, με τον ίππο να δίνει ματ.";i['enPassantDescription']="Τακτικά που αφορούν τον κανόνα en passant, σύμφωνα με τον οποίο ένα πιόνι μπορεί να αιχμαλωτίσει ένα αντίπαλο πιόνι το οποίο προσπέρασε κινούμενο από την αρχική του θέση δύο τετράγωνα μπροστά.";i['forkDescription']="Μια κίνηση κατά την οποία το μετακινούμενο κομμάτι επιτίθεται ταυτόχρονα σε δύο ή περισσότερα αντίπαλα κομμάτια.";i['hookMateDescription']="Ματ με πύργο, ίππο, και ένα πιόνι, μαζί με ένα αντίπαλο πιόνι το οποίο εμποδίζει την διαφυγή του αντίπαλου βασιλιά.";i['morphysMateDescription']="Ένας αξιωματικός κάνει σαχ στον αντίπαλο βασιλιά, περιορίζοντάς τον με τη βοήθεια ενός πύργου.";i['pillsburysMateDescription']="Ο πύργος κάνει ματ στον αντίπαλο βασιλιά, τον οποίο ένας αξιωματικός έχει περιορίσει.";i['promotionDescription']="Προάγετε ένα πιόνι σας σε μια βασίλισσα ή σε κάποιο ελαφρύ κομμάτι."})()